using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static partial class HedgeDetailUpdater {
static void AuditAtlasSpace(){string matPath="Assets/Scenes/Oasis/3D/Fbx/Materials/Pertrol pump.mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(matPath);var tex=mat.GetTexture("_BaseMap");var meshes=new Dictionary<Mesh,string>();int renderers=0;foreach(string path in AssetDatabase.FindAssets("t:Prefab").Select(AssetDatabase.GUIDToAssetPath)){var go=PrefabUtility.LoadPrefabContents(path);foreach(var r in go.GetComponentsInChildren<Renderer>(true))if(r.sharedMaterials.Contains(mat)){renderers++;var mf=r.GetComponent<MeshFilter>();if(mf&&mf.sharedMesh)meshes[mf.sharedMesh]=path+"/"+r.name;}PrefabUtility.UnloadPrefabContents(go);}foreach(var mf in UnityEngine.Object.FindObjectsOfType<MeshFilter>(true)){var r=mf.GetComponent<Renderer>();if(r&&r.sharedMaterials.Contains(mat)&&mf.sharedMesh)meshes[mf.sharedMesh]="scene/"+mf.name;}int n=256;var occ=new bool[n,n];string details="Texture="+AssetDatabase.GetAssetPath(tex)+" size="+tex.width+"x"+tex.height+"\nMaterial users="+renderers+" meshes="+meshes.Count+"\n";foreach(var pair in meshes){var data=Read(pair.Key);var u=F<Vector2[][]>(data,"uv")[0];var id=F<int[]>(data,"ids");for(int t=0;t+2<id.Length;t+=3){Vector2 a=u[id[t]];Vector2 b=u[id[t+1]];Vector2 c=u[id[t+2]];int minx=Mathf.Clamp(Mathf.FloorToInt(Mathf.Min(a.x,b.x,c.x)*n),0,n-1),maxx=Mathf.Clamp(Mathf.FloorToInt(Mathf.Max(a.x,b.x,c.x)*n),0,n-1),miny=Mathf.Clamp(Mathf.FloorToInt(Mathf.Min(a.y,b.y,c.y)*n),0,n-1),maxy=Mathf.Clamp(Mathf.FloorToInt(Mathf.Max(a.y,b.y,c.y)*n),0,n-1);for(int y=miny;y<=maxy;y++)for(int x=minx;x<=maxx;x++){var p=new Vector2((x+.5f)/n,(y+.5f)/n);float den=(b.y-c.y)*(a.x-c.x)+(c.x-b.x)*(a.y-c.y);if(Mathf.Abs(den)<1e-8f)continue;float wa=((b.y-c.y)*(p.x-c.x)+(c.x-b.x)*(p.y-c.y))/den,wb=((c.y-a.y)*(p.x-c.x)+(a.x-c.x)*(p.y-c.y))/den,wc=1-wa-wb;if(wa>=0&&wb>=0&&wc>=0)occ[x,y]=true;}}}int best=0,bx=0,by=0,bw=0,bh=0;for(int y=0;y<n;y++)for(int x=0;x<n;x++)if(!occ[x,y]){int w=0;while(x+w<n&&!occ[x+w,y])w++;int h=1;while(y+h<n&&Enumerable.Range(x,w).All(xx=>!occ[xx,y+h]))h++;if(w*h>best){best=w*h;bx=x;by=y;bw=w;bh=h;}}details+="largest empty rect UV="+(float)bx/n+","+(float)by/n+","+(float)bw/n+","+(float)bh/n+" px="+(float)bw/n*tex.width+"x"+(float)bh/n*tex.height+"\n";File.WriteAllText("FinalEnvironmentRoadReview/HedgeAtlasSpace.txt",details);}
}

